/**
 * Messages, cut 1 (the spine): one thread per person. Every call, voicemail, missed call, text, email, team note and
 * event with them, oldest first, with a divider at each new day and the job a line is tied to; whose move it is from
 * the last word each way; the when in words. Lifted from the Messages prototype (branch spike/gc-mode,
 * `to-dos/gc-mode/messages/prototype.html` v1.178: `lastInOnly`, `lastOut`, `courtOf`, `agoWords`, `whenWords`,
 * `snippetOf`, `chWord`, `fmt`, `dayOf`, `isLong`, the thread loop in `renderMessages`). Days are Chicago's, read
 * through `utils/dateUtils`, never the browser's.
 */
import {
  APP_CALENDAR_TZ,
  calendarYmdInAppTzFromIso,
  companyWeekStartSundayContaining,
  ymdDaysBetween,
} from '../../utils/dateUtils.ts'
import type { LineFile } from './lineFileTypes.ts'

export type MessageChannel = 'call' | 'voicemail' | 'missed' | 'text' | 'email' | 'note' | 'event' | 'portal'

/** In: from them. Out: from us. Team: a note or an event, which only the office sees. */
export type MessageDirection = 'in' | 'out' | 'team'

/** A message as the thread reads it, one `messages` row. */
export interface ThreadMessage {
  id: string
  contactId: string
  /** The job it is tied to. Null: on the person, no job. */
  jobId: string | null
  channel: MessageChannel
  direction: MessageDirection
  /** When it came, went or was written. */
  at: string
  /** The line's who: "Robert answered", "Rosa · bids@", "rang everyone on the company number". */
  who: string
  /** An email's subject. */
  subject?: string | null
  body: string
  /** The `contact_channels` row it came from or went to: the number or the address. Null on a note or an event. */
  channelId?: string | null
  /** A call's or a voicemail's length in seconds, as Quo reports it. `callLength` writes it "4:12". */
  durationSeconds?: number | null
  /** The opt-out line this text carried: the first text to a number, again after a silence, or held back. */
  optoutLine?: 'first' | 'silence' | 'held' | null
  /** A team note's day to come back to Follow up, and who set it. */
  backOn?: string | null
  backBy?: string | null
  /** The files and links it came or went with, in order (cut 6, `lineFiles.ts`; the type in `lineFileTypes.ts`). */
  files?: readonly LineFile[]
  /**
   * The box it came in on or went out from (R6, `messages.mailbox`): the team box or bids@. Null on a line from before
   * R6, a note or an event. Written out here, not imported from `boxes.ts`, so the edge copy of this file stays light.
   */
  mailbox?: 'team' | 'bids' | null
}

const byTime = (a: { at: string }, b: { at: string }) => Date.parse(a.at) - Date.parse(b.at)

/** Their thread, oldest first. With a job, only the lines tied to it. */
export function threadOf(messages: readonly ThreadMessage[], contactId: string, jobId: string | null = null): ThreadMessage[] {
  return messages.filter((m) => m.contactId === contactId && (!jobId || m.jobId === jobId)).sort(byTime)
}

const newest = (messages: readonly ThreadMessage[], keep: (m: ThreadMessage) => boolean): ThreadMessage | undefined => {
  const kept = messages.filter(keep).sort(byTime)
  return kept[kept.length - 1]
}

/** Their last word to us: the newest call, voicemail, missed call, text, email or portal line from them. */
export function lastIn(messages: readonly ThreadMessage[], contactId: string): ThreadMessage | undefined {
  return newest(messages, (m) => m.contactId === contactId && m.direction === 'in')
}

/** Our last word to them. */
export function lastOut(messages: readonly ThreadMessage[], contactId: string): ThreadMessage | undefined {
  return newest(messages, (m) => m.contactId === contactId && m.direction === 'out')
}

/** The newest line either way, a team note included, an event not. */
export function lastMessage(messages: readonly ThreadMessage[], contactId: string): ThreadMessage | undefined {
  return newest(messages, (m) => m.contactId === contactId && m.channel !== 'event')
}

const CHANNEL_WORD: Record<MessageChannel, string> = {
  call: 'Call',
  voicemail: 'Voicemail',
  missed: 'Missed call',
  text: 'Text',
  email: 'Email',
  note: 'Note',
  event: 'Event',
  portal: 'Portal',
}

/** "Missed call": a line's kind, as its meta line and the stamps name it. */
export function channelWord(m: { channel: MessageChannel }): string {
  return CHANNEL_WORD[m.channel]
}

/** What a row shows of a line: an email's subject or first line, a missed call's "no voicemail", else the words. */
export function snippetOf(m: Pick<ThreadMessage, 'channel' | 'subject' | 'body'>): string {
  if (m.channel === 'email') return m.subject?.trim() || (m.body.split('\n')[0] ?? '')
  if (m.channel === 'missed') return 'no voicemail'
  return m.body
}

/** A call's or a voicemail's length on its meta line: "4:12", "0:38", "1:02:05". */
export function callLength(seconds: number): string {
  const s = Math.max(0, Math.round(seconds))
  const two = (n: number) => String(n).padStart(2, '0')
  if (s >= 3600) return `${Math.floor(s / 3600)}:${two(Math.floor((s % 3600) / 60))}:${two(s % 60)}`
  return `${Math.floor(s / 60)}:${two(s % 60)}`
}

/** A line the thread folds to four lines until it is opened: over four lines, or over 280 characters. */
export function isLong(m: Pick<ThreadMessage, 'body'>): boolean {
  return m.body.split('\n').length > 4 || m.body.length > 280
}

// ---------- the when, in Chicago ----------

const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'] as const
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'] as const
const MONTHS_LONG = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'] as const

const weekday = (dow: number): string => WEEKDAYS[dow] ?? ''
const month = (m: number): string => MONTHS[m - 1] ?? ''

const ymdParts = (ymd: string) => {
  const [y, m, d] = ymd.split('-').map(Number) as [number, number, number]
  return { y, m, d, dow: new Date(Date.UTC(y, m - 1, d)).getUTCDay() }
}

/** The Chicago day of an instant, "2026-10-02". */
export function chicagoDay(iso: string): string {
  return calendarYmdInAppTzFromIso(iso)
}

/** Whole Chicago days from `atIso` to `nowIso`: 0 today, 1 yesterday. */
export function daysAgo(atIso: string, nowIso: string): number {
  return ymdDaysBetween(chicagoDay(atIso), chicagoDay(nowIso)) ?? 0
}

/** "8:44 AM" in Chicago. */
export function clockTime(iso: string): string {
  const parts = new Intl.DateTimeFormat('en-US', { timeZone: APP_CALENDAR_TZ, hour: 'numeric', minute: '2-digit', hour12: true }).formatToParts(
    new Date(iso),
  )
  const get = (t: Intl.DateTimeFormatPartTypes) => parts.find((p) => p.type === t)?.value ?? ''
  return `${get('hour')}:${get('minute')} ${get('dayPeriod').toUpperCase()}`
}

/** "Oct 1", with the year when it is not this year's: "Oct 1, 2025". */
function monthDay(ymd: string, nowYmd: string): string {
  const { y, m, d } = ymdParts(ymd)
  return `${month(m)} ${d}${String(y) === nowYmd.slice(0, 4) ? '' : `, ${y}`}`
}

/** A thread's day divider: "Today, Fri Oct 2", "Thursday, Oct 1". */
export function dayLabel(atIso: string, nowIso: string): string {
  const ymd = chicagoDay(atIso)
  const nowYmd = chicagoDay(nowIso)
  const { dow } = ymdParts(ymd)
  if (ymd === nowYmd) return `Today, ${weekday(dow).slice(0, 3)} ${monthDay(ymd, nowYmd)}`
  return `${weekday(dow)}, ${monthDay(ymd, nowYmd)}`
}

/** A line's when: "today · 8:44 AM", or "Thu, Oct 1 · 3:10 PM". */
export function lineWhen(atIso: string, nowIso: string): string {
  const ymd = chicagoDay(atIso)
  const nowYmd = chicagoDay(nowIso)
  if (ymd === nowYmd) return `today · ${clockTime(atIso)}`
  return `${weekday(ymdParts(ymd).dow).slice(0, 3)}, ${monthDay(ymd, nowYmd)} · ${clockTime(atIso)}`
}

/** The when on a line's hover card: "Friday, October 2, 2026 at 8:44 AM". */
export function fullWhen(atIso: string): string {
  const { y, m, d, dow } = ymdParts(chicagoDay(atIso))
  return `${weekday(dow)}, ${MONTHS_LONG[m - 1] ?? ''} ${d}, ${y} at ${clockTime(atIso)}`
}

/** How long ago, short: "4 min", "3 h", "6 d". */
export function agoWords(atIso: string, nowIso: string): string {
  const mins = Math.max(1, Math.round((Date.parse(nowIso) - Date.parse(atIso)) / 60_000))
  if (mins < 60) return `${mins} min`
  if (mins < 60 * 24) return `${Math.round(mins / 60)} h`
  return `${Math.round(mins / 1440)} d`
}

const WEEKS_BACK = ['', 'last week', 'two weeks ago', 'three weeks ago'] as const

/**
 * The when in words, for a sentence: "today at 8:44 AM", "yesterday", "on Wednesday" this week, "last Saturday", "last
 * week", "two weeks ago", "three weeks ago", then "on Sep 5". Weeks start on Sunday.
 */
export function whenWords(atIso: string, nowIso: string): string {
  const n = daysAgo(atIso, nowIso)
  if (n <= 0) return `today at ${clockTime(atIso)}`
  if (n === 1) return 'yesterday'
  const ymd = chicagoDay(atIso)
  const nowYmd = chicagoDay(nowIso)
  const thisSunday = companyWeekStartSundayContaining(nowYmd) ?? nowYmd
  if (n <= 6) {
    const day = weekday(ymdParts(ymd).dow)
    return ymd >= thisSunday ? `on ${day}` : `last ${day}`
  }
  // Days before this week's Sunday, in weeks, rounded up: the week just gone is 1, its Sunday included.
  const weeksBack = Math.ceil((ymdDaysBetween(ymd, thisSunday) ?? 0) / 7)
  if (weeksBack >= 1 && weeksBack <= 3) return WEEKS_BACK[weeksBack] ?? ''
  return `on ${monthDay(ymd, nowYmd)}`
}

// ---------- whose move ----------

export interface Court {
  /** Ours: the last word was theirs, or we owe them something. Theirs: the last word was ours. None: nothing waits. */
  side: 'ours' | 'theirs' | 'none'
  /** The strip's words: "Our move · 2 h", "Their move · until Wed Oct 7 · quote", "no messages yet". */
  word: string
  /** The message the clock counts from. */
  sinceIso?: string
  /** True when it is ours because we owe them something, which stays ours after we write. */
  owed?: true
}

export interface CourtOptions {
  /** No way left to answer them in writing (`isOptedOut` in contacts/kernel). */
  optedOut?: boolean
  /** What we owe them and by when (cut 2's `contact_owed`). */
  owed?: { what: string; by?: string | null } | null
  /** Their running promise's line, which their move runs until (cut 2's `runningPromise(...).until`): "until Wed Oct 7 · quote". */
  promisedUntil?: string | null
}

/**
 * Whose move it is: ours when their word is the newest or we owe them something, theirs when ours is, counted from that
 * word. A team note moves nothing.
 */
export function courtOf(messages: readonly ThreadMessage[], contactId: string, nowIso: string, opts: CourtOptions = {}): Court {
  if (opts.optedOut) return { side: 'none', word: 'opted out' }
  if (opts.owed) {
    const by = opts.owed.by ? ` · by ${opts.owed.by}` : ''
    return { side: 'ours', word: `Our move · we owe ${opts.owed.what}${by}`, owed: true }
  }
  const i = lastIn(messages, contactId)
  const o = lastOut(messages, contactId)
  if (!i && !o) return { side: 'none', word: 'no messages yet' }
  if (i && (!o || Date.parse(i.at) > Date.parse(o.at))) return { side: 'ours', word: `Our move · ${agoWords(i.at, nowIso)}`, sinceIso: i.at }
  const last = o!
  const word = opts.promisedUntil ? `Their move · ${opts.promisedUntil}` : `Their move · ${agoWords(last.at, nowIso)}`
  return { side: 'theirs', word, sinceIso: last.at }
}

// ---------- the thread's rows ----------

export type ThreadRow =
  /** A divider at each new Chicago day. */
  | { kind: 'day'; ymd: string; label: string }
  /** A gray event line: "Rosa marked the bid lost. · 5:05 PM". */
  | { kind: 'event'; message: ThreadMessage; time: string }
  /**
   * A message. `job` says how its job reads: the badge and the name, the badge alone when the line before it on the same
   * day was tied to the same job, or none when it is on the person.
   */
  | { kind: 'line'; message: ThreadMessage; job: 'full' | 'number' | 'none' }

/** Where the rows stand while they are drawn: the day of the last divider, and the job of the last line on it. */
export interface ThreadRowState {
  day: string
  lastJob: string | null
}

/** Lines oldest first, as the thread draws them. */
export function byTimeOldestFirst<T extends { at: string }>(lines: readonly T[]): T[] {
  return [...lines].sort(byTime)
}

/**
 * One line onto the rows: its day's divider when its day is new, then the event or the line with how its job reads.
 * `threadRows`' rule, and the app's folded runs' (`appLines.ts`, `foldedThreadRows`) for the lines they draw.
 */
export function pushThreadRow(rows: { push(row: ThreadRow): unknown }, state: ThreadRowState, m: ThreadMessage, nowIso: string): void {
  const ymd = chicagoDay(m.at)
  if (ymd !== state.day) {
    rows.push({ kind: 'day', ymd, label: dayLabel(m.at, nowIso) })
    state.day = ymd
    state.lastJob = null
  }
  if (m.channel === 'event') {
    // An event never breaks a run of one job.
    rows.push({ kind: 'event', message: m, time: clockTime(m.at) })
    return
  }
  const job = !m.jobId ? 'none' : m.jobId === state.lastJob ? 'number' : 'full'
  state.lastJob = m.jobId
  rows.push({ kind: 'line', message: m, job })
}

/** The thread as the screen draws it, oldest first: day dividers, events and lines. */
export function threadRows(lines: readonly ThreadMessage[], nowIso: string): ThreadRow[] {
  const rows: ThreadRow[] = []
  const state: ThreadRowState = { day: '', lastJob: null }
  for (const m of byTimeOldestFirst(lines)) pushThreadRow(rows, state, m, nowIso)
  return rows
}
